// Compute the convex hull of a set of integer points.
// Return the hull's corner points in counter-clockwise order, starting from the
// smallest point (smallest x, ties broken by smallest y). Points that lie on a
// hull edge but are not corners are left out, and duplicate points count once.
//
// Degenerate cases: no points give []; if all points are equal, return
// that single point; if all points lie on one line, return its two endpoints,
// smallest first. Return [] if any coordinate has absolute value greater
// than 1_000_000_000.
//
// Examples:
//   convex_hull([(0, 0), (4, 0), (4, 4), (0, 4), (2, 2)]) == [(0, 0), (4, 0), (4, 4), (0, 4)]
//   convex_hull([(1, 1), (3, 3), (2, 2)]) == [(1, 1), (3, 3)]
fn convex_hull(points: List[(Int, Int)]) -> List[(Int, Int)] {
  let limit = 1_000_000_000;
  if any(points, |p| abs(p.0) > limit || abs(p.1) > limit) {
    return [];
  }
  // Sort lexicographically by (x, y): in range, this key is order-preserving.
  let sorted = sort_by(points, |p| (p.0 + limit) * (2 * limit + 1) + (p.1 + limit));
  let mut pts: List[(Int, Int)] = [];
  for p in sorted {
    if last(pts) != Some(p) {
      pts = push(pts, p);
    }
  }
  if len(pts) <= 2 {
    return pts;
  }
  let lower = chain(pts);
  let upper = chain(reverse(pts));
  take(lower, len(lower) - 1) ++ take(upper, len(upper) - 1)
}

fn cross(o: (Int, Int), a: (Int, Int), b: (Int, Int)) -> Int {
  (a.0 - o.0) * (b.1 - o.1) - (a.1 - o.1) * (b.0 - o.0)
}

// One half of Andrew's monotone chain; drops collinear points.
fn chain(seq: List[(Int, Int)]) -> List[(Int, Int)] {
  let mut out: List[(Int, Int)] = [];
  for p in seq {
    while len(out) >= 2 && cross(out[len(out) - 2], out[len(out) - 1], p) <= 0 {
      out = take(out, len(out) - 1);
    }
    out = push(out, p);
  }
  out
}
